import java.sql.*;

public class SecureDatabaseAccess {

  public static void main(String[] args) {
    String url = "jdbc:mysql://localhost:3306/mydatabase";
    String user = "myuser";
    String password = "mypassword";

    try (Connection conn = DriverManager.getConnection(url, user, password)) {
      // Safe: Using parameterized query
      String userInput = "1"; 
      String sql = "SELECT * FROM users WHERE username = ?"; 
      PreparedStatement stmt = conn.prepareStatement(sql);
      stmt.setString(1, userInput);
      ResultSet rs = stmt.executeQuery();

      while (rs.next()) {
        System.out.println(rs.getString("username"));
      }
    } catch (SQLException e) {
      e.printStackTrace();
    }
  }
}
```

**Explanation:**

This code snippet demonstrates a secure approach by using a parameterized query. The `?` placeholder in the `sql` string acts as a marker for the user input (`userInput`) which is safely bound to the query using `stmt.setString(1, userInput)`. This prevents the attacker from injecting malicious SQL code as the input is treated as a data value rather than executable code.

